import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

const String _arbPath = 'lib/app/l10n/app_en.arb';
const String _outputPath = 'test/helpers/pseudo_localizations.dart';

/// The `pseudo` function of the generated file.
const String _pseudoSource = r'''
/// [s] with its vowels, c and n accented, padded by 40% and bracketed, so
/// text that is cut, or never translated, shows. The values in [keep] (a
/// message's placeholder values) are copied as they are.
String pseudo(String s, [List<Object> keep = const []]) {
  const from = 'aeioucnAEIOUCN';
  const to = 'áéíóúçñÁÉÍÓÚÇÑ';
  final kept = [
    for (final k in keep)
      if ('$k'.isNotEmpty) '$k',
  ];
  final out = StringBuffer();
  var i = 0;
  while (i < s.length) {
    String? match;
    for (final k in kept) {
      if (s.startsWith(k, i) &&
          (match == null || k.length > match.length)) {
        match = k;
      }
    }
    if (match != null) {
      out.write(match);
      i += match.length;
      continue;
    }
    final j = from.indexOf(s[i]);
    out.write(j < 0 ? s[i] : to[j]);
    i++;
  }
  final padding = '·' * (s.length * 0.4).ceil();
  return '⟦$out$padding⟧';
}''';

/// The source of `test/helpers/pseudo_localizations.dart`, generated from
/// the English template [arb] (Ruling P8-R9): every message is overridden to
/// return the English text through `pseudo`.
String generatePseudoLocalizations(Map<String, dynamic> arb) {
  final out = StringBuffer()
    ..writeln('// GENERATED by pseudo_localizations_test.dart. Do not edit.')
    ..writeln('// dart format off')
    ..writeln('// ignore_for_file: type=lint')
    ..writeln()
    ..writeln("import 'package:flutter/foundation.dart';")
    ..writeln("import 'package:flutter/widgets.dart';")
    ..writeln("import 'package:tv_remote/app/l10n/app_localizations.dart';")
    ..writeln("import 'package:tv_remote/app/l10n/app_localizations_en.dart';")
    ..writeln()
    ..writeln(_pseudoSource)
    ..writeln('/// The English strings through [pseudo]; a test-only locale.')
    ..writeln('class PseudoLocalizations extends AppLocalizationsEn {')
    ..writeln('  /// The pseudo strings.')
    ..writeln('  PseudoLocalizations();')
    ..writeln()
    ..writeln('  /// Loads [PseudoLocalizations] for any locale.')
    ..writeln(
      '  static const LocalizationsDelegate<AppLocalizations> delegate =',
    )
    ..writeln('      _PseudoLocalizationsDelegate();');
  for (final key in arb.keys) {
    if (key.startsWith('@')) continue;
    final meta = arb['@$key'] as Map<String, dynamic>?;
    final placeholders =
        (meta?['placeholders'] as Map<String, dynamic>?) ?? const {};
    out.writeln();
    if (placeholders.isEmpty) {
      out
        ..writeln('  @override')
        ..writeln('  String get $key => pseudo(super.$key);');
      continue;
    }
    final params = [
      for (final MapEntry(key: name, :value) in placeholders.entries)
        '${(value as Map<String, dynamic>)['type'] ?? 'Object'} $name',
    ].join(', ');
    final args = placeholders.keys.join(', ');
    out
      ..writeln('  @override')
      ..writeln(
        '  String $key($params) => pseudo(super.$key($args), [$args]);',
      );
  }
  out
    ..writeln('}')
    ..writeln()
    ..writeln(
      'class _PseudoLocalizationsDelegate '
      'extends LocalizationsDelegate<AppLocalizations> {',
    )
    ..writeln('  const _PseudoLocalizationsDelegate();')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  bool isSupported(Locale locale) => true;')
    ..writeln()
    ..writeln('  @override')
    ..writeln('  Future<AppLocalizations> load(Locale locale) =>')
    ..writeln(
      '      SynchronousFuture<AppLocalizations>(PseudoLocalizations());',
    )
    ..writeln()
    ..writeln('  @override')
    ..writeln(
      '  bool shouldReload(_PseudoLocalizationsDelegate old) => false;',
    )
    ..writeln('}');
  return out.toString();
}

void main() {
  test('pseudo_localizations_source_is_current', () {
    final arb =
        jsonDecode(File(_arbPath).readAsStringSync()) as Map<String, dynamic>;
    final source = generatePseudoLocalizations(arb);
    final file = File(_outputPath);
    if (autoUpdateGoldenFiles) {
      file.writeAsStringSync(source);
      return;
    }
    // A checkout may turn LF into CRLF (core.autocrlf).
    expect(
      file.readAsStringSync().replaceAll('\r\n', '\n'),
      source,
      reason:
          '$_outputPath is stale: run flutter test --update-goldens '
          'test/app/l10n/pseudo_localizations_test.dart',
    );
  });
}
